CREATE TABLE applicants (id UUID PRIMARY KEY, name VARCHAR(120) NOT NULL, student_id VARCHAR(64) NOT NULL UNIQUE, major VARCHAR(120) NOT NULL, study_year INTEGER NOT NULL CHECK (study_year BETWEEN 1 AND 8), university_status VARCHAR(32) NOT NULL, applicant_role VARCHAR(32) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE applicant_courses (applicant_id UUID NOT NULL REFERENCES applicants(id) ON DELETE CASCADE, course VARCHAR(160) NOT NULL, PRIMARY KEY (applicant_id, course));
